after(() => { process.env.HOME = prev; fs.rmSync(home, { recursive: true, force: true }); });
const quiet = (a: AutonomousAgent) => { (a as any).ui = new Proxy({}, { get: () => () => {} }); return a; };
const cfg = (endpoint: string, workspace: string, o: Partial<HarnessConfig> = {}): HarnessConfig => ({ endpoint, model: "m", maxSteps: 30, temperature: 0, workspace, shell: "bash", approvalMode: "auto", fullAccess: true, continuation: { ...DEFAULT_CONTINUATION, stagnationSteps: 30, maxRecoveries: 2 }, ...o });
type Call = { name: string; args: unknown };
const tools = (calls: Call[]): Reply => ({ kind: "tools", calls });
const text = (content: string): Reply => ({ kind: "text", content });
function dispatchLog(agent: AutonomousAgent) {
  const log: Array<{ id: string; name: string; args: string }> = [];
  const original = (agent as any).dispatchToolCall.bind(agent);
  (agent as any).dispatchToolCall = async (call: any, ...rest: unknown[]) => { log.push({ id: call.id, name: call.function.name, args: JSON.stringify(call.function.arguments) }); return original(call, ...rest); };
  return log;
}
const refusalMsgs = (a: AutonomousAgent) => a.getMessages().filter((m: any) => m.role === "tool" && String(m.content).startsWith("[Nexus refused"));

test("R1 gitignored file rewritten earlier in the same batch: re-read refused?", { timeout: 120_000 }, async () => {
  const repo = makeRepo({ ".gitignore": "out/\n" });
  fs.mkdirSync(path.join(repo, "out"));
  fs.writeFileSync(path.join(repo, "out/r.txt"), "v1\n");
  const r = { name: "read_file", args: { path: "out/r.txt" } };
  const gw = await startGateway((n) => {
    if (n <= 4) return tools([r]);
    if (n === 5) return tools([{ name: "run_command", args: { command: "echo v2-NEW > out/r.txt" } }, r]);
    return text("done");
  });
  const agent = quiet(new AutonomousAgent(cfg(gw.url, repo)));
  const ran = dispatchLog(agent);
  try {
